/*!
 * Bootstrap-compatible local JavaScript for CRICKETARENA.
 * Implements the navbar collapse behavior used by this project.
 */
(function () {
  "use strict";

  document.addEventListener("click", function (event) {
    var toggle = event.target.closest("[data-bs-toggle='collapse']");

    if (!toggle) {
      return;
    }

    var targetSelector = toggle.getAttribute("data-bs-target");
    var target = document.querySelector(targetSelector);

    if (!target) {
      return;
    }

    var isOpen = target.classList.toggle("show");
    toggle.setAttribute("aria-expanded", isOpen ? "true" : "false");
  });
})();
